52	export const createFighter = async (data: {
53	  first_name: string;
54	  last_name: string;
55	  nickname?: string;
56	}): Promise<Fighter> => {
57	  const response = await fetch('/fighters/', {
58	    method: 'POST',
59	    headers: { 'Content-Type': 'application/json' },
60	    body: JSON.stringify(data),
61	  });
62	  if (!response.ok) throw new Error(`Failed to create fighter: ${response.statusText}`);
63	  return response.json();
