              <div className="glass" style={{ padding: '9px 11px', borderRadius: 9, borderLeft: `3px solid ${hover.color}` }}>
                <div style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-primary)', lineHeight: 1.3 }}>{hover.e.description}</div>
