        </button>
        <button className="icon-btn" title="Zoom in" onClick={() => setZoom(z => Math.min(12, +(z + 0.5).toFixed(1)))} style={{ width: 28, height: 28 }}>
          <span className="material-symbols-outlined" style={{ fontSize: 17 }}>add</span>
        </button>
      </div>
    </div>
  );
}

